import { describe, it, expect } from 'vitest';
import { importIptablesConfig } from './index.js';
import { compileNftables } from '../../compile/nft/index.js';
import { DesiredStateSchema } from '../../schemas/index.js';

const SAMPLE_IPTABLES_SAVE = `
# Generated by iptables-save v1.8.9
*nat
:PREROUTING ACCEPT [0:0]
:INPUT ACCEPT [0:0]
:OUTPUT ACCEPT [0:0]
:POSTROUTING ACCEPT [0:0]
-A PREROUTING -i eth0 -p tcp -m tcp --dport 8080 -j DNAT --to-destination 192.168.1.50:80 --comment "Web Port Forward"
-A POSTROUTING -o eth0 -j MASQUERADE --comment "WAN Masquerade"
COMMIT
*filter
:INPUT DROP [0:0]
:FORWARD DROP [0:0]
:OUTPUT ACCEPT [0:0]
-A INPUT -m conntrack --ctstate RELATED,ESTABLISHED -j ACCEPT
-A INPUT -i lo -j ACCEPT
-A INPUT -i eth1 -p tcp -m tcp --dport 22 -j ACCEPT --comment "Allow Admin SSH"
-A INPUT -p icmp -j ACCEPT --comment "Allow Ping"
-A FORWARD -m conntrack --ctstate RELATED,ESTABLISHED -j ACCEPT
-A FORWARD -i eth1 -o eth0 -j ACCEPT --comment "Allow LAN outbound to WAN"
-A FORWARD -i eth0 -o eth1 -p tcp -d 192.168.1.50 --dport 80 -j ACCEPT --comment "Allow Forwarded Web"
COMMIT
`;

describe('Linux iptables / nftables Importer', () => {
  it('parses iptables-save dumps into Axonwall DesiredState and compiles to nftables', () => {
    const report = importIptablesConfig(SAMPLE_IPTABLES_SAVE);

    expect(report.success).toBe(true);
    expect(report.vendor).toBe('iptables');
    expect(report.interfacesCount).toBeGreaterThanOrEqual(2);
    expect(report.rulesCount).toBe(4);
    expect(report.natRulesCount).toBe(2);

    // NAT
    expect(report.state.nat[0].type).toBe('dnat');
    expect(report.state.nat[0].targetIp).toBe('192.168.1.50');
    expect(report.state.nat[0].targetPort).toBe('80');
    expect(report.state.nat[1].type).toBe('masquerade');

    // Rules
    expect(report.state.rules[0].action).toBe('pass');
    expect(report.state.rules[0].destinationPort).toBe('22');
    expect(report.state.rules[0].description).toBe('Allow Admin SSH');

    const { nftScript } = compileNftables(report.state);
    expect(nftScript).toContain('table inet axonwall');
    expect(nftScript).toContain('192.168.1.50');
    expect(() => DesiredStateSchema.parse(report.state)).not.toThrow();
  });

  it('does not flatten custom-chain ACCEPT rules into active global rules [SEC-H20]', () => {
    const ipt = `
*filter
:INPUT DROP [0:0]
:TRUSTED_SSH - [0:0]
-A INPUT -s 10.0.0.0/8 -j TRUSTED_SSH
-A TRUSTED_SSH -p tcp --dport 22 -j ACCEPT --comment "Admin SSH in custom chain"
COMMIT
`;
    const report = importIptablesConfig(ipt);
    expect(report.rulesCount).toBe(1);
    const rule = report.state.rules[0]!;
    expect(rule.enabled).toBe(false);
    expect(rule.description).toContain('Custom chain TRUSTED_SSH');
    expect(report.reviewItems?.some((ri) => ri.reason === 'manual_review')).toBe(true);
    expect(report.warnings.length).toBeGreaterThanOrEqual(2);

    const { nftScript } = compileNftables(report.state);
    expect(nftScript).not.toContain('dport 22');
    expect(() => DesiredStateSchema.parse(report.state)).not.toThrow();
  });

  it('emits invertSource and invertDestination on ! negated matches while keeping them disabled [SEC-H20]', () => {
    const ipt = `
*filter
:INPUT DROP [0:0]
-A INPUT ! -s 10.0.0.0/8 -p tcp --dport 22 -j ACCEPT --comment "Negated prefix src"
-A INPUT -s ! 192.168.1.0/24 -d !172.16.0.0/12 -p udp --dport 53 -j DROP --comment "Negated both"
-A INPUT ! -p tcp -j ACCEPT --comment "Unsupported negated proto"
COMMIT
`;
    const report = importIptablesConfig(ipt);
    expect(report.rulesCount).toBe(3);

    expect(report.state.rules[0]!.source).toBe('10.0.0.0/8');
    expect(report.state.rules[0]!.invertSource).toBe(true);
    expect(report.state.rules[0]!.invertDestination).toBeUndefined();
    expect(report.state.rules[0]!.enabled).toBe(false);

    expect(report.state.rules[1]!.source).toBe('192.168.1.0/24');
    expect(report.state.rules[1]!.invertSource).toBe(true);
    expect(report.state.rules[1]!.destination).toBe('172.16.0.0/12');
    expect(report.state.rules[1]!.invertDestination).toBe(true);
    expect(report.state.rules[1]!.enabled).toBe(false);
    expect(report.reviewItems?.some((ri) => ri.reason === 'negated_both')).toBe(true);

    expect(report.state.rules[2]!.enabled).toBe(false);
    expect(report.reviewItems?.some((ri) => ri.reason === 'manual_review')).toBe(true);
    expect(() => DesiredStateSchema.parse(report.state)).not.toThrow();
  });

  it('does not skip DROP or REJECT rules matching ESTABLISHED,RELATED [SEC-H20]', () => {
    const ipt = `
*filter
:INPUT DROP [0:0]
-A INPUT -m conntrack --ctstate ESTABLISHED,RELATED -j DROP --comment "Drop stateful"
-A FORWARD -s 203.0.113.5 -m state --state RELATED,ESTABLISHED -j REJECT --comment "Reject stateful"
-A INPUT -m conntrack --ctstate RELATED,ESTABLISHED -j ACCEPT
COMMIT
`;
    const report = importIptablesConfig(ipt);
    expect(report.rulesCount).toBe(2);
    expect(report.state.rules[0]!.action).toBe('block');
    expect(report.state.rules[0]!.enabled).toBe(true);
    expect(report.state.rules[1]!.action).toBe('reject');
    expect(report.state.rules[1]!.source).toBe('203.0.113.5');
    expect(report.state.rules[1]!.enabled).toBe(true);
    expect(() => DesiredStateSchema.parse(report.state)).not.toThrow();
  });
});
